create table if not exists public.ace_institutions(id uuid primary key default gen_random_uuid(),name text not null unique,short_name text not null,country text not null default 'Kenya',created_at timestamptz not null default now());create table if not exists public.ace_programmes(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.ace_institutions(id),name text not null,school text,unique(institution_id,name));create table if not exists public.ace_course_catalog(id uuid primary key default gen_random_uuid(),programme_id uuid not null references public.ace_programmes(id),code text not null,title text not null,year_of_study smallint check(year_of_study between 1 and 10),semester smallint check(semester between 1 and 3),unique(programme_id,code));alter table public.ace_institutions enable row level security;alter table public.ace_programmes enable row level security;alter table public.ace_course_catalog enable row level security;create policy ace_institutions_read on public.ace_institutions for select to authenticated using(true);create policy ace_programmes_read on public.ace_programmes for select to authenticated using(true);create policy ace_catalog_read on public.ace_course_catalog for select to authenticated using(true);grant select on public.ace_institutions,public.ace_programmes,public.ace_course_catalog to authenticated;